/// Verifies that a buffer of bytes contains a `APM`
/// and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_apm_unchecked`.
#[inline]
pub fn root_as_apm(buf: &[u8]) -> Result<APM<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root::<APM>(buf)
}

/// Verifies that a buffer of bytes contains a size prefixed
/// `APM` and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `size_prefixed_root_as_apm_unchecked`.
#[inline]
pub fn size_prefixed_root_as_apm(buf: &[u8]) -> Result<APM<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root::<APM>(buf)
}

/// Verifies, with the given options, that a buffer of bytes
/// contains a `APM` and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_apm_unchecked`.
#[inline]
pub fn root_as_apm_with_opts<'b, 'o>(
    opts: &'o ::flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<APM<'b>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root_with_opts::<APM<'b>>(opts, buf)
}

/// Verifies, with the given verifier options, that a buffer of
/// bytes contains a size prefixed `APM` and returns
/// it. Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_apm_unchecked`.
#[inline]
pub fn size_prefixed_root_as_apm_with_opts<'b, 'o>(
    opts: &'o ::flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<APM<'b>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root_with_opts::<APM<'b>>(opts, buf)
}

/// Assumes, without verification, that a buffer of bytes contains a APM and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid `APM`.
#[inline]
pub unsafe fn root_as_apm_unchecked(buf: &[u8]) -> APM<'_> {
    unsafe { ::flatbuffers::root_unchecked::<APM>(buf) }
}

/// Assumes, without verification, that a buffer of bytes contains a size prefixed APM and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid size prefixed `APM`.
#[inline]
pub unsafe fn size_prefixed_root_as_apm_unchecked(buf: &[u8]) -> APM<'_> {
    unsafe { ::flatbuffers::size_prefixed_root_unchecked::<APM>(buf) }
}

pub const APM_IDENTIFIER: &str = "$APM";

#[inline]
pub fn apm_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, APM_IDENTIFIER, false)
}

#[inline]
pub fn apm_size_prefixed_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, APM_IDENTIFIER, true)
}

#[inline]
pub fn finish_apm_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<APM<'a>>
) {
    fbb.finish(root, Some(APM_IDENTIFIER));
}

#[inline]
pub fn finish_size_prefixed_apm_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<APM<'a>>
) {
    fbb.finish_size_prefixed(root, Some(APM_IDENTIFIER));
}
